CREATE TABLE received_dispatch_groups (id UUID PRIMARY KEY, group_no VARCHAR(50) NOT NULL, dispatch_date DATE NOT NULL, vehicle_label VARCHAR(100) NOT NULL, carrier_code VARCHAR(50) NOT NULL, carrier_name VARCHAR(100) NOT NULL, slip_snapshot TEXT NOT NULL, created_at TIMESTAMP NOT NULL, created_by VARCHAR(50) NOT NULL, modified_at TIMESTAMP, modified_by VARCHAR(50), deleted_at TIMESTAMP, deleted_by VARCHAR(50), is_deleted BOOLEAN NOT NULL DEFAULT FALSE);
CREATE UNIQUE INDEX ux_received_dispatch_groups_group_no_active ON received_dispatch_groups(group_no) WHERE is_deleted = FALSE;
